/-- Every supported cell effect is within `sigma*M` of the ATE. -/
def ApproximateHomogeneity {d : ℕ} (M sigma : ℝ) (P : RealLaw d) : Prop :=
  ∀ k, 0 < P.cellMass k → |cellDeviation P k| ≤ sigma * M

/-- Binary laws in the cited exact-homogeneity source experiment. -/
def BinaryExactLaw (_n d : ℕ) (epsilon : ℝ) :=
  {P : BinLaw d // BinaryExactHomogeneous epsilon P}

/-- `Y = Y(A)` almost surely under the full-data law. -/
def Consistency {d : ℕ} (P : RealLaw d) : Prop :=
  P.fullLaw {z | z.y ≠ if z.a then z.y1 else z.y0} = 0

/-- Total estimators with measurable output clipped to `[-M,M]`. -/
def Estimator (n d : ℕ) (M : ℝ) :=
  {f : (Fin n → Obs d) → ℝ // Measurable f ∧ ∀ x, f x ∈ Icc (-M) M}

/-- Projection from full data to the observed record. -/
def FullObs.observed {d : ℕ} (z : FullObs d) : Obs d :=
  ⟨z.x, z.a, z.y⟩ -- @realizes O(O=(X,A,Y))

/-- Conditional means lie in `[-M/2,M/2]` on positive-mass cells. -/
def MeanNormalization {d : ℕ} (M : ℝ) (P : RealLaw d) : Prop :=
  ∀ a k, 0 < P.cellMass k → |P.outcomeMean a k| ≤ M / 2

/-- Standing range condition for the known outcome scale. -/
def OutcomeScale (M : ℝ) : Prop :=
  1 ≤ M

/-- Number of observations in arm `a` and cell `k`. -/
def armCount {n d : ℕ} (sample : Fin n → Obs d) (a : Bool) (k : Fin d) : ℕ :=
  (Finset.univ.filter fun i => (sample i).x = k ∧ (sample i).a = a).card

/-- This augments an observed binary record with an independently drawn missing potential outcome. -/
def binaryIndependentLift {d : ℕ} (z : BinObs d) (other : Bool) : BinaryFullObs d :=
  if z.2.1 then ⟨z.1, true, other, z.2.2⟩ else ⟨z.1, false, z.2.2, other⟩

/-- This Boolean marked pattern adds the distinguished arm to the tail pattern. -/
def boolMarkedPattern (j : ℕ) (a b : Bool) : Fin (j + 2) → Bool :=
  Fin.cons a (boolTailPattern j a b)

/-- This Boolean tail pattern records whether each remaining coordinate matches a designated arm. -/
def boolTailPattern (j : ℕ) (a b : Bool) : Fin (j + 1) → Bool :=
  Fin.cases b (fun _ => a)

/-- Total number of observations in cell `k`. -/
def cellCount {n d : ℕ} (sample : Fin n → Obs d) (k : Fin d) : ℕ :=
  armCount sample false k + armCount sample true k

/-- Cell treatment effect `tau_k = mu_1k - mu_0k`. -/
def cellEffect {d : ℕ} (P : RealLaw d) (k : Fin d) : ℝ :=
  P.outcomeMean true k - P.outcomeMean false k

/-- Population collision weight for cell `k`. -/
def collisionWeight {d : ℕ} (P : RealLaw d) (k : Fin d) : ℝ :=
  2 * P.cellMass k ^ 2 * P.propensity k * (1 - P.propensity k)

/-- Estimation-block cell count. -/
def estimationCellCount {n d : ℕ} (sample : Fin n → Obs d) (k : Fin d) : ℕ :=
  estimationArmCount sample false k + estimationArmCount sample true k

/-- Pilot occupancy of one cell. -/
def pilotCount {n d : ℕ} (sample : Fin n → Obs d) (k : Fin d) : ℕ :=
  (Finset.univ.filter fun i => inPilot i ∧ (sample i).x = k).card

/-- If [the indicated calibration branch applies](hyp:hbranch), [the calibrated branch has a
  concrete aggregate program with the advertised budget](goal). -/
lemma polynomialComplexityBound_of_calibrated {n d : ℕ}
    {handle : PolynomialHandle} {M : ℝ}
    (hbranch : handle.N ≤ n ∧ (d : ℝ) ≤ handle.rho * n * logEN n) :
    PolynomialExactComplexityCertificate n d handle M := by
  let program : AggregatedPolynomialProgram n d handle M :=
    { code := calibratedPolynomialCode n d M
      computesEstimator := by
        intro sample
        rw [calibratedPolynomialCode_computes]
        simp [polyEstimator, rawPolyEstimator, hbranch, polynomialNormalizedSum] }
  exact ⟨program, calibratedPolynomialCode_operationCount_le n d M⟩

/-- Regroup an arm-cell count vector into false/true counts within each cell. -/
def regroupArmCellCounts {d : ℕ} (c : Fin d × Bool → ℕ) : Fin d → ℕ × ℕ :=
  fun k => (c (k, false), c (k, true))

/-- The zero-occupancy indicator on a stream prefix. -/
def streamUsableZero {d : ℕ} (n : ℕ) (z : ℕ → Fin d × Bool) : ℝ≥0∞ :=
  if streamUsableTotal z n = 0 then 1 else 0

/-- Whether both treatment arms occur in a cell. -/
def usableCell {n d : ℕ} (sample : Fin n → Obs d) (k : Fin d) : Bool :=
  decide (0 < armCount sample false k ∧ 0 < armCount sample true k)

/-- Total occupancy among cells containing both treatment arms. -/
def usableTotal {n d : ℕ} (sample : Fin n → Obs d) : ℕ :=
  ∑ k : Fin d, if usableCell sample k then cellCount sample k else 0

/-- Usable occupancy computed from a regrouped pair of arm counts. -/
def usableTotalOfRegroupedCounts {d : ℕ} (c : Fin d → ℕ × ℕ) : ℕ :=
  ∑ k : Fin d, if 0 < (c k).1 ∧ 0 < (c k).2 then (c k).1 + (c k).2 else 0
